-- CT-02i: private media draft foundation. STAGED ONLY. NO HOSTED SQL.
-- Filename generated by pinned Supabase CLI 3.2.0 in Actions 45306452322.
-- Requires CT-02b/c/e/f/g/h installed with approved staff membership/grants.
-- Does not change 'media' bucket, existing media_assets, published image URLs,
-- imported ownerless files, or the currently disabled app feature flags.
begin;

-- Do not silently adopt an existing bucket with unknown visibility/policies.
do $fn$
begin
  if exists(select 1 from storage.buckets where id='media-drafts') then
    raise exception 'media-drafts already exists: review before CT-02i rollout';
  end if;
end;
$fn$;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values (
  'media-drafts',
  'media-drafts',
  false,
  10485760,
  array['image/jpeg','image/png','image/webp','image/gif','image/avif']::text[]
);

-- Isolated staging catalog: deliberately not part of the existing media_assets
-- publication pipeline. No public URL or approval/promote action is created.
create table public.media_private_drafts (
  id uuid primary key default gen_random_uuid(),
  uploaded_by uuid not null references auth.users(id),
  bucket_id text not null default 'media-drafts' check (bucket_id='media-drafts'),
  storage_path text not null unique,
  file_name text not null check (char_length(file_name) between 1 and 255),
  mime_type text not null check (mime_type in (
    'image/jpeg','image/png','image/webp','image/gif','image/avif'
  )),
  file_size_bytes bigint not null check (file_size_bytes between 1 and 10485760),
  created_at timestamptz not null default now(),
  check (storage_path like 'drafts/' || uploaded_by::text || '/%')
);
create index ct02i_media_private_drafts_owner_created
on public.media_private_drafts(uploaded_by,created_at desc);

alter table public.media_private_drafts enable row level security;
revoke all on public.media_private_drafts from public,anon,authenticated;
grant select,insert on public.media_private_drafts to authenticated;

create policy ct02i_private_draft_read
on public.media_private_drafts for select to authenticated using (
  newsroom_private.has_staff_permission('media.view_all')
  or newsroom_private.has_staff_permission('media.edit_all')
  or (
    uploaded_by=(select auth.uid())
    and newsroom_private.has_staff_permission('media.upload')
  )
);

-- A record may only reference an actually uploaded private object, owned by
-- this user. Do not allow client-supplied object paths owned by colleagues.
create policy ct02i_private_draft_insert
on public.media_private_drafts for insert to authenticated with check (
  uploaded_by=(select auth.uid())
  and newsroom_private.has_staff_permission('media.upload')
  and exists (
    select 1 from storage.objects o
    where o.bucket_id='media-drafts'
      and o.name=storage_path
      and o.owner_id=(select auth.uid())::text
  )
);

-- Storage policy scope is limited to the NEW PRIVATE bucket.
-- Existing media bucket RLS from CT-02g is intentionally untouched.
create policy ct02i_storage_private_read
on storage.objects for select to authenticated using (
  bucket_id='media-drafts'
  and (
    newsroom_private.has_staff_permission('media.view_all')
    or newsroom_private.has_staff_permission('media.edit_all')
    or (
      owner_id=(select auth.uid())::text
      and newsroom_private.has_staff_permission('media.upload')
    )
  )
);

create policy ct02i_storage_private_insert
on storage.objects for insert to authenticated with check (
  bucket_id='media-drafts'
  and owner_id=(select auth.uid())::text
  and newsroom_private.has_staff_permission('media.upload')
  and name like 'drafts/' || (select auth.uid())::text || '/%'
  and split_part(name,'/',3)<>''
  and split_part(name,'/',4)=''
);

-- No UPDATE permission: private drafts cannot be overwritten/upserted,
-- renamed or moved directly via a URL. Changes use new upload identities.
-- DELETE is only for one authenticated owner's unlinked, failed upload.
create policy ct02i_storage_private_orphan_cleanup
on storage.objects for delete to authenticated using (
  bucket_id='media-drafts'
  and owner_id=(select auth.uid())::text
  and newsroom_private.has_staff_permission('media.upload')
  and not exists (
    select 1 from public.media_private_drafts d
    where d.bucket_id=bucket_id and d.storage_path=name
  )
);

-- Deliberately no public SELECT, approval, publishing, copy or promotion.
-- An approved/private-to-public workflow is a distinct, reviewed next batch.
commit;
